BEGIN;

ON CONFLICT(id) DO UPDATE SET
  address=COALESCE(importyeti_web_entities.address,excluded.address),country=COALESCE(importyeti_web_entities.country,excluded.country),country_code=COALESCE(importyeti_web_entities.country_code,excluded.country_code),website=COALESCE(importyeti_web_entities.website,excluded.website),total_shipments=CASE WHEN COALESCE(importyeti_web_entities.total_shipments,0)>COALESCE(excluded.total_shipments,0) THEN importyeti_web_entities.total_shipments ELSE excluded.total_shipments END,latest_shipment_date=CASE WHEN COALESCE(importyeti_web_entities.latest_shipment_date,'')>COALESCE(excluded.latest_shipment_date,'') THEN importyeti_web_entities.latest_shipment_date ELSE excluded.latest_shipment_date END,contact_data_status=CASE WHEN importyeti_web_entities.contact_data_status IN ('official_contact_found','verified') THEN importyeti_web_entities.contact_data_status ELSE excluded.contact_data_status END,raw_evidence=COALESCE(importyeti_web_entities.raw_evidence,excluded.raw_evidence),identity_confidence=CASE WHEN COALESCE(importyeti_web_entities.identity_confidence,0)>COALESCE(excluded.identity_confidence,0) THEN importyeti_web_entities.identity_confidence ELSE excluded.identity_confidence END,identity_notes=COALESCE(importyeti_web_entities.identity_notes,excluded.identity_notes),updated_at=excluded.updated_at;

ON CONFLICT(id) DO UPDATE SET importer_id=COALESCE(importyeti_web_shipments.importer_id,excluded.importer_id),weight_kg=COALESCE(importyeti_web_shipments.weight_kg,excluded.weight_kg),quantity=COALESCE(importyeti_web_shipments.quantity,excluded.quantity),product_description=COALESCE(importyeti_web_shipments.product_description,excluded.product_description);

ON CONFLICT(id) DO UPDATE SET shipment_count=CASE WHEN importyeti_web_relationships.shipment_count>excluded.shipment_count THEN importyeti_web_relationships.shipment_count ELSE excluded.shipment_count END,period_start=COALESCE(importyeti_web_relationships.period_start,excluded.period_start),period_end=CASE WHEN COALESCE(importyeti_web_relationships.period_end,'')>excluded.period_end THEN importyeti_web_relationships.period_end ELSE excluded.period_end END,hs_codes=COALESCE(importyeti_web_relationships.hs_codes,excluded.hs_codes),product_descriptions=COALESCE(importyeti_web_relationships.product_descriptions,excluded.product_descriptions);

ON CONFLICT(company_id) DO UPDATE SET status=excluded.status,notes=CASE WHEN length(buyer_watchlist.notes)>=length(excluded.notes) THEN buyer_watchlist.notes ELSE excluded.notes END,lead_status=CASE WHEN buyer_watchlist.lead_status IN ('contacted','follow_up','qualified','opportunity') THEN buyer_watchlist.lead_status ELSE excluded.lead_status END,outreach_strategy=COALESCE(buyer_watchlist.outreach_strategy,excluded.outreach_strategy),recommended_products=COALESCE(buyer_watchlist.recommended_products,excluded.recommended_products),confidence=COALESCE(buyer_watchlist.confidence,excluded.confidence),commercial_fit_score=COALESCE(buyer_watchlist.commercial_fit_score,excluded.commercial_fit_score),outreach_score=COALESCE(buyer_watchlist.outreach_score,excluded.outreach_score),updated_at=excluded.updated_at;

ON CONFLICT(normalized_company_name) DO UPDATE SET company_id=COALESCE(lead_contact_research.company_id,excluded.company_id),status=excluded.status,reason_code=excluded.reason_code,reason=excluded.reason,next_action=excluded.next_action,evidence_urls=excluded.evidence_urls,researched_at=excluded.researched_at,updated_at=excluded.updated_at;

ON CONFLICT(id) DO UPDATE SET contact_value=excluded.contact_value,label=excluded.label,source_url=excluded.source_url,verified_at=excluded.verified_at,verification_status=excluded.verification_status,notes=CASE WHEN length(lead_contacts.notes)>=length(excluded.notes) THEN lead_contacts.notes ELSE excluded.notes END,updated_at=excluded.updated_at;

ON CONFLICT(id) DO NOTHING;


I’m reaching out from Yundor, a bathroom-product manufacturing partner supporting international brands and distributors. Danco’s focus on plumbing repair, faucet, shower and mobile-home bathroom products aligns closely with our certified showerhead, faucet, drain and coordinated component capabilities.

We can support OEM/ODM development, compliance documentation, finish consistency, component-level quality control and export-ready fulfillment from China. Our strongest starting point for Danco would be certified showerheads, mobile-home faucets, and faucet or drain components designed around an established repair assortment.

Would a short product-fit review with your sourcing or product-development team be useful? If this form reaches another department, I would appreciate being directed to the appropriate contact.

Best regards,
Yundor Business Development','draft','Danco Inc: 4,845 public shipment records with activity through 2026-05-22. Exact recent cargo includes drains, shower tools and strainers, faucet repair components and plumbing rubber parts. Official product categories include bathroom, showerhead, faucet and mobile-home/RV lines.','Submit only after manual review. Do not claim knowledge of confidential purchasing needs. Use the official form business/department selectors to reach sourcing or product development; alternatively call the official number for routing. Lead with compliance-ready component and repair assortment support, not a generic full-bathroom collection.','2026-08-08T23:30:00.000Z','2026-08-08T23:30:00.000Z')
ON CONFLICT(id) DO UPDATE SET subject=CASE WHEN lead_outreach_drafts.status='archived' THEN excluded.subject ELSE lead_outreach_drafts.subject END,body=CASE WHEN lead_outreach_drafts.status='archived' THEN excluded.body ELSE lead_outreach_drafts.body END,status=CASE WHEN lead_outreach_drafts.status='archived' THEN 'draft' ELSE lead_outreach_drafts.status END,evidence_summary=excluded.evidence_summary,personalization_notes=excluded.personalization_notes,updated_at=CASE WHEN lead_outreach_drafts.status='archived' THEN excluded.updated_at ELSE lead_outreach_drafts.updated_at END;

COMMIT;
